def merge(left, right):
    results = []
    while left and right:
        if left[0][1] > right[0][1]:
            results.append(left.pop(0))
        else:
            results.append(right.pop(0))
    results.extend(left)
    results.extend(right)
    return results

def merge_sort(lst):
