def merge(one,two):
    new_tup = []
    while one and two:
        if one[0][1] < two[0][1]:
            new_tup.append(two.pop(0))
        else:
            new_tup.append(one.pop(0))
    new_tup.extend(one)
    new_tup.extend(two)
    return new_tup

def sort_age(lst):
    n = len(lst)
    if n <2:
        return lst
    mid = n // 2
    left = lst[:mid]
    right = lst[mid:]
    return merge(sort_age(left), sort_age(right))

